<template>
  <ion-page class="onboarding-page"><ion-content :fullscreen="true" class="ion-padding"><main class="onboarding-shell"><section><p class="eyebrow">首次开通</p><h1>创建你的门店</h1><p>完成后会自动生成顾客扫码入口和专属管理空间。</p></section><form class="onboarding-form" @submit.prevent="submit"><ion-item><ion-input v-model="form.name" label="门店名称" label-placement="stacked" placeholder="例如：惠民五金店" :maxlength="120" :counter="true" required /></ion-item><ion-item><ion-input v-model="form.address" label="门店地址" label-placement="stacked" placeholder="用于顾客到店导航" :maxlength="200" :counter="true" required /></ion-item><div class="onboarding-grid"><ion-item><ion-input v-model="form.phone" label="联系电话（可选）" label-placement="stacked" inputmode="tel" :maxlength="20" placeholder="13800000000" /></ion-item><ion-item><ion-label position="stacked">开店时间</ion-label><ion-input v-model="form.openingTime" type="time" required /></ion-item><ion-item><ion-label position="stacked">关店时间</ion-label><ion-input v-model="form.closingTime" type="time" required /></ion-item></div><ion-note v-if="error" color="danger" class="auth-error">{{ error }}</ion-note><ion-button type="submit" expand="block" :disabled="saving">{{ saving ? '正在创建…' : '创建门店并继续' }}</ion-button></form></main></ion-content></ion-page>
</template>
<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { IonPage, IonContent, IonItem, IonInput, IonButton, IonNote, IonLabel } from '@ionic/vue'; import { useAuth } from '@/composables/useAuth'; import { businessHours, validateStoreProfile } from '@/services/store-profile-validation';
const router=useRouter();const {onboardStore}=useAuth();const saving=ref(false);const error=ref('');const form=reactive({name:'',address:'',phone:'',openingTime:'08:00',closingTime:'21:00'});
async function submit(){error.value='';const profile=validateStoreProfile({name:form.name,address:form.address,phone:form.phone,hours:businessHours(form.openingTime,form.closingTime),welcome:`欢迎来到${form.name.trim()}，请问有什么可以帮您？`});if(!profile.valid){error.value=profile.errors.join('；');return;}saving.value=true;try{await onboardStore(profile.profile);await router.replace('/settings?welcome=1');}catch(caught){error.value=caught instanceof Error?caught.message:'门店创建失败，请重试';}finally{saving.value=false;}}
</script>
